# ---- input helpers ----
def get_int(prompt, low, high):
    """Keep asking until a whole number from low to high is typed; return it."""
    while True:
        text = input(prompt)
        if not text.isdigit():
            print("Please type a whole number.")
        elif int(text) < low or int(text) > high:
            print("Must be from", low, "to", high)
        else:
            return int(text)

def get_text(prompt):
    """Keep asking until something other than blank is typed; return it stripped."""
    while True:
        text = input(prompt).strip()
        if text != "":
            return text
        print("This cannot be blank.")

# ---- file handling ----
def load_members(filename):
    """Return a list of [name, year, points] read from filename; empty list if missing."""
    members = []
    try:
        with open(filename) as f:
            for line in f:
                line = line.strip()
                if line != "":
                    parts = line.split(",")
                    members.append([parts[0], int(parts[1]), int(parts[2])])
    except FileNotFoundError:
        pass
    return members

def save_members(members, filename):
    """Write every record to filename as name,year,points, replacing the file."""
    with open(filename, "w") as f:
        for m in members:
            f.write(m[0] + "," + str(m[1]) + "," + str(m[2]) + "\n")

